function daysPast(due: string | null): number {
  if (!due) return 0;
  const d = new Date(due).getTime();
  if (Number.isNaN(d)) return 0;
  return Math.floor((Date.now() - d) / (1000 * 60 * 60 * 24));
}

function toIsoDate(value: string | null | undefined): string | null {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const actor = await requireActor();
  if (!actor) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { authUser: user, ownerId } = actor;
  if (isDemoEmail(user.email)) {
    return NextResponse.json({ error: DEMO_READONLY_MESSAGE }, { status: 403 });
  }

  const { id } = await params;
  const b = (await req.json().catch(() => ({}))) as {
    paid?: boolean;
    amount_cents?: number;
    due_date?: string | null;
    memo?: string | null;
  };

  const sb = adminSupabase();
  const { data: existing } = await sb
    .from("invoices_invoices")
    .select("id, client_id, due_date, status, paid_date")
    .eq("user_id", ownerId)
    .eq("id", id)
    .maybeSingle();
  if (!existing) return NextResponse.json({ error: "Invoice not found." }, { status: 404 });

  const nowIso = new Date().toISOString();
  const patch: Record<string, unknown> = { updated_at: nowIso };

  if (typeof b.amount_cents === "number") {
    const amount = Math.round(b.amount_cents);
    if (!(amount > 0)) {
      return NextResponse.json({ error: "Enter an amount greater than zero." }, { status: 400 });
    }
    patch.amount_cents = amount;
  }
  if (b.due_date !== undefined) patch.due_date = toIsoDate(b.due_date);
  if (b.memo !== undefined) patch.memo = (b.memo ?? "").trim() || null;

  // Status is derived, never free-set: paid wins, otherwise due-date math.
  const dueAfter = (b.due_date !== undefined ? toIsoDate(b.due_date) : existing.due_date) as
    | string
    | null;
  const paidAfter = b.paid !== undefined ? b.paid === true : existing.status === "paid";
  const status: InvoiceStatus = paidAfter ? "paid" : daysPast(dueAfter) > 0 ? "overdue" : "open";
  patch.status = status;
  patch.paid_date = paidAfter ? (existing.paid_date ?? nowIso) : null;

  const { error } = await sb
    .from("invoices_invoices")
    .update(patch)
    .eq("user_id", ownerId)
    .eq("id", id);
  if (error) return NextResponse.json({ error: "Couldn't save the invoice." }, { status: 500 });

  if (existing.client_id) await recomputeClientOutstanding(ownerId, existing.client_id);

  revalidateUser("invoices", ["invoices", "clients"], ownerId);
  return NextResponse.json({ id, status });
}
